// A single document in an "orders" collection
{
  _id: ObjectId("66f1c2a9e4b0a1b2c3d4e5f6"),
  customer: { name: "Ana", email: "ana@example.com" },
  items: [
    { sku: "PEN-01", qty: 3, price: Decimal128("1.50") },
    { sku: "PAD-07", qty: 1, price: Decimal128("4.20") }
  ],
  status: "paid",
  createdAt: ISODate("2026-10-01T09:30:00Z")
}

use shop
db.products.insertOne({ _id: "PEN-01", name: "Pen", price: 1.5 })
// { acknowledged: true, insertedId: 'PEN-01' }

db.products.insertMany(
  [
    { _id: "PAD-07", name: "Notepad", price: 4.2 },
    { _id: "PEN-01", name: "Duplicate pen" },   // duplicate _id
    { _id: "INK-02", name: "Ink", price: 3 }
  ],
  { ordered: false }
)
// MongoBulkWriteError: E11000 duplicate key error ... dup key: { _id: "PEN-01" }
db.products.countDocuments()   // 3  (PAD-07 and INK-02 were still inserted)

db.users.insertMany([
  { name: "Ana", age: 31, address: { city: "Yerevan" }, tags: ["admin"] },
  { name: "Ben", age: 25, address: { city: "Gyumri" } },
  { name: "Cy",  age: 31, address: { city: "Yerevan" }, nickname: null }
])
db.users.find({ "address.city": "Yerevan", age: 31 }, { _id: 0, name: 1 })
// [ { name: 'Ana' }, { name: 'Cy' } ]
db.users.findOne({ name: "Ben" }, { address: 0, _id: 0 })
// { name: 'Ben', age: 25 }
db.users.find({ nickname: null }, { _id: 0, name: 1 })
// Ana, Ben and Cy: null also matches a missing field

db.orders.insertMany([
  { n: 1, status: "paid",    total: 40,  coupon: "FALL" },
  { n: 2, status: "shipped", total: 150 },
  { n: 3, status: "new",     total: 90,  spent: 120, budget: 100 }
])
db.orders.find({ total: { $gte: 50, $lt: 200 } }, { _id: 0, n: 1 })
// [ { n: 2 }, { n: 3 } ]
db.orders.find({ $or: [{ status: "paid" }, { total: { $gt: 100 } }] }, { _id: 0, n: 1 })
// [ { n: 1 }, { n: 2 } ]
db.orders.find({ coupon: { $exists: false } }, { _id: 0, n: 1 })   // n: 2 and 3
db.orders.find({ status: { $ne: "paid" } }, { _id: 0, n: 1 })      // n: 2 and 3
db.orders.find({ $expr: { $gt: ["$spent", "$budget"] } }, { _id: 0, n: 1 })  // n: 3

for (let i = 1; i <= 7; i++) db.posts.insertOne({ _id: i, likes: i % 3 })
db.posts.find({}, { likes: 1 }).sort({ likes: -1, _id: 1 }).limit(3)
// [ { _id: 2, likes: 2 }, { _id: 5, likes: 2 }, { _id: 1, likes: 1 } ]

// page 2 with skip (fine for small offsets)
db.posts.find().sort({ _id: 1 }).skip(3).limit(3).map(d => d._id)   // [ 4, 5, 6 ]

// keyset paging: continue after the last _id seen
const lastId = 3
db.posts.find({ _id: { $gt: lastId } }).sort({ _id: 1 }).limit(3).map(d => d._id)
// [ 4, 5, 6 ]
db.posts.countDocuments({ likes: { $gt: 0 } })   // 5

db.stock.insertOne({ _id: "PEN-01", qty: 10, tags: ["office"] })
db.stock.updateOne(
  { _id: "PEN-01" },
  { $inc: { qty: -3 }, $addToSet: { tags: "sale" }, $currentDate: { updatedAt: true } }
)
// { acknowledged: true, matchedCount: 1, modifiedCount: 1, upsertedCount: 0, ... }
db.stock.findOne({ _id: "PEN-01" }, { qty: 1, tags: 1 })
// { _id: 'PEN-01', qty: 7, tags: [ 'office', 'sale' ] }

db.pageviews.updateOne({ page: "/home" }, { $inc: { views: 1 } }, { upsert: true })
// first call: upsertedCount: 1 and creates { page: '/home', views: 1 }
db.stock.updateOne({ _id: "PEN-01" }, { qty: 0 })
// MongoInvalidArgumentError: Update document requires atomic operators

db.sessions.insertMany([
  { user: "ana", createdAt: new Date() },
  { user: "ben", createdAt: new Date("2020-01-01") },
  { user: "cy",  createdAt: new Date("2020-01-02") }
])
db.sessions.countDocuments({ createdAt: { $lt: new Date("2021-01-01") } })  // 2: check first
db.sessions.deleteMany({ createdAt: { $lt: new Date("2021-01-01") } })
// { acknowledged: true, deletedCount: 2 }
db.sessions.findOneAndDelete({ user: "ana" })   // returns the removed document

// let the server expire sessions after 1 hour from now on
db.sessions.createIndex({ createdAt: 1 }, { expireAfterSeconds: 3600 })
db.sessions.drop()   // true: collection and its indexes are gone

db.carts.insertOne({ _id: 1, items: [ { sku: "PEN", qty: 2 }, { sku: "PAD", qty: 9 } ] })

db.carts.countDocuments({ "items.sku": "PEN", "items.qty": { $gt: 5 } })  // 1 (different elements!)
db.carts.countDocuments({ items: { $elemMatch: { sku: "PEN", qty: { $gt: 5 } } } })  // 0

// set qty of the PAD element only
db.carts.updateOne({ _id: 1, "items.sku": "PAD" }, { $set: { "items.$.qty": 1 } })
// add 10 to every element with qty < 5
db.carts.updateOne(
  { _id: 1 },
  { $inc: { "items.$[low].qty": 10 } },
  { arrayFilters: [ { "low.qty": { $lt: 5 } } ] }
)
db.carts.findOne({ _id: 1 }).items
// [ { sku: 'PEN', qty: 12 }, { sku: 'PAD', qty: 11 } ]

db.orders.createIndex({ customerId: 1, createdAt: -1, total: 1 })

// E (customerId) + S (createdAt) + R (total): one IXSCAN, no SORT stage
db.orders.find({ customerId: 42, total: { $gt: 100 } }).sort({ createdAt: -1 })

// prefix use: also served by the same index
db.orders.find({ customerId: 42 })

// not a prefix: cannot use this index efficiently
db.orders.find({ createdAt: { $gte: ISODate("2026-01-01") } })

// covered query: only indexed fields, _id excluded, no FETCH stage
db.orders.find({ customerId: 42 }, { _id: 0, createdAt: 1, total: 1 })

db.sales.insertMany([
  { region: "north", item: "pen", qty: 10, price: 1.5, day: ISODate("2026-10-01") },
  { region: "north", item: "pad", qty: 2,  price: 4,   day: ISODate("2026-10-01") },
  { region: "south", item: "pen", qty: 5,  price: 1.5, day: ISODate("2026-10-02") },
  { region: "south", item: "ink", qty: 1,  price: 9,   day: ISODate("2026-10-03") }
])
db.sales.aggregate([
  { $match: { day: { $gte: ISODate("2026-10-01") } } },
  { $set: { revenue: { $multiply: ["$qty", "$price"] } } },
  { $group: { _id: "$region", revenue: { $sum: "$revenue" }, orders: { $count: {} } } },
  { $sort: { revenue: -1 } }
])
// [ { _id: 'north', revenue: 23, orders: 2 },
//   { _id: 'south', revenue: 16.5, orders: 2 } ]

// Embedded: one read renders the order page, one atomic write updates it
{ _id: 9001, customerId: 42, status: "paid",
  shipTo: { city: "Yerevan", street: "Abovyan 1" },
  items: [ { sku: "PEN-01", name: "Pen", qty: 3, price: 1.5 } ] }

// Referenced + extended reference: customers live in their own collection,
// the order copies only the name it needs to display
{ _id: 9002, customer: { _id: 42, name: "Ana" }, items: [ ... ] }

// Subset pattern: product keeps its 3 newest reviews, all reviews elsewhere
{ _id: "PEN-01", name: "Pen", reviewCount: 812,
  recentReviews: [ { by: "ben", stars: 5 }, { by: "cy", stars: 4 }, { by: "di", stars: 5 } ] }

import { MongoClient, ObjectId } from "mongodb";

const client = new MongoClient(process.env.MONGODB_URI ?? "mongodb://localhost:27017");
const orders = client.db("shop").collection("orders");   // reuse these everywhere

async function main() {
  const { insertedId } = await orders.insertOne({ customer: "ana", total: 12.5 });
  const doc = await orders.findOne({ _id: new ObjectId(insertedId.toString()) });
  console.log(doc.total);                                  // 12.5

  for await (const o of orders.find({ total: { $gt: 10 } }).sort({ total: -1 })) {
    console.log(o.customer);                               // ana
  }
  const res = await orders.updateMany({ customer: "ana" }, { $set: { vip: true } });
  console.log(res.modifiedCount);                          // 1
}
main().finally(() => client.close());

db.customers.insertMany([ { _id: 1, name: "Ana" }, { _id: 2, name: "Ben" } ])
db.orders.insertMany([
  { _id: 10, customerId: 1, items: [ { sku: "PEN", qty: 3 }, { sku: "PAD", qty: 1 } ] },
  { _id: 11, customerId: 1, items: [ { sku: "PEN", qty: 2 } ] }
])
db.orders.aggregate([
  { $lookup: { from: "customers", localField: "customerId", foreignField: "_id", as: "c" } },
  { $set: { customer: { $first: "$c.name" } } },
  { $unwind: "$items" },
  { $group: { _id: { customer: "$customer", sku: "$items.sku" }, qty: { $sum: "$items.qty" } } },
  { $sort: { qty: -1 } }
])
// [ { _id: { customer: 'Ana', sku: 'PEN' }, qty: 5 },
//   { _id: { customer: 'Ana', sku: 'PAD' }, qty: 1 } ]

db.createCollection("users", {
  validator: { $jsonSchema: {
    bsonType: "object",
    required: ["email", "createdAt"],
    properties: {
      email:     { bsonType: "string", pattern: "^.+@.+$" },
      age:       { bsonType: "int", minimum: 0, maximum: 150 },
      role:      { enum: ["user", "admin"] },
      createdAt: { bsonType: "date" }
    }
  } },
  validationAction: "error"
})
db.users.insertOne({ email: "ana@x.io", createdAt: new Date(), role: "user" })  // ok
db.users.insertOne({ email: "nope", createdAt: new Date() })
// MongoServerError: Document failed validation

// three-member set, run once on one member
rs.initiate({ _id: "rs0", members: [
  { _id: 0, host: "db1:27017" }, { _id: 1, host: "db2:27017" }, { _id: 2, host: "db3:27017" } ] })
rs.status().members.map(m => m.stateStr)   // [ 'PRIMARY', 'SECONDARY', 'SECONDARY' ]

// durable write: acknowledged once a majority has it, fail after 5 s
db.payments.insertOne({ amount: 50 }, { writeConcern: { w: "majority", wtimeout: 5000 } })

// analytics read from a secondary, accepting slight staleness
db.payments.find().readPref("secondaryPreferred")

// connection string form
// mongodb://db1,db2,db3/?replicaSet=rs0&w=majority&readPreference=primaryPreferred

// Node.js driver: transfer money between two account documents
const session = client.startSession();
try {
  await session.withTransaction(async () => {
    const accounts = client.db("bank").collection("accounts");
    const from = await accounts.findOneAndUpdate(
      { _id: "ana", balance: { $gte: 100 } },
      { $inc: { balance: -100 } },
      { session, returnDocument: "after" });
    if (!from) throw new Error("insufficient funds");   // aborts the transaction
    await accounts.updateOne({ _id: "ben" }, { $inc: { balance: 100 } }, { session });
  }, { writeConcern: { w: "majority" } });
} finally {
  await session.endSession();
}

// via mongos
sh.enableSharding("shop")                 // optional since 6.0, harmless
db.orders.createIndex({ tenantId: 1, orderId: 1 })
sh.shardCollection("shop.orders", { tenantId: 1, orderId: 1 })

// targeted: includes the shard key prefix -> one or few shards
db.orders.find({ tenantId: "acme", status: "open" })
// scatter-gather: no shard key -> every shard is queried
db.orders.find({ status: "open" })

// hashed alternative for events that are only ever added, never edited
sh.shardCollection("shop.events", { deviceId: "hashed" })
db.orders.getShardDistribution()          // data and docs per shard

db.orders.createIndex({ status: 1 })
db.orders.createIndex({ createdAt: -1 })

const q = { status: "open", createdAt: { $gte: ISODate("2026-10-01") } }
const ex = db.orders.find(q).sort({ createdAt: -1 }).explain("allPlansExecution")
ex.queryPlanner.winningPlan           // which index won the trial
ex.queryPlanner.rejectedPlans.length  // 1

db.orders.getPlanCache().list().length    // cached shapes for this collection
db.orders.find(q).sort({ createdAt: -1 }).hint({ status: 1 })   // force an index
db.setProfilingLevel(1, { slowms: 100 })   // log slow operations to system.profile
db.system.profile.find().sort({ ts: -1 }).limit(1)
// best fix here: one ESR index { status: 1, createdAt: -1 }
